xpath.attribute:
'o_nav_entry' + ((env.services.router.current && (
                    env.services.router.current.hash.menu_id == section.id || 
                    (section.childrenTree && section.childrenTree.some(c => 
                        env.services.router.current.hash.menu_id == c.id || 
                        (c.childrenTree && c.childrenTree.some(cc => 
                            env.services.router.current.hash.menu_id == cc.id
                        ))
                    ))
                )) ? ' active' : '')

(env.services.router.current && (
                    env.services.router.current.hash.menu_id == section.id || 
                    (section.childrenTree && section.childrenTree.some(c => 
                        env.services.router.current.hash.menu_id == c.id || 
                        (c.childrenTree && c.childrenTree.some(cc => 
                            env.services.router.current.hash.menu_id == cc.id
                        ))
                    ))
                )) ? 'active' : ''
